      id: 'lore_purity_rules',
      name: '洁净与不洁',
      description:
        '不洁不是罪，是一种状态：碰过尸体、碰过经血、发过假誓、跟不洁的人同席吃饭、被狗咬过（有些地方这么算），都会让人不洁一段时间。不洁的人不能进庙、不能作证、不能立契。恢复洁净的办法各个庙不一样，最便宜的是洗三遍河水，最贵的是献一只羊。这条规矩在城里最厉害的地方是：它能让一个人在没有被判任何罪的情况下，失去全部的生计。',
      attribute: 'bond',
      level: 2,
