        '三十四岁的平原女性，沙玛庙库房的女管事，也是全乌尔沙少数几个可以自己盖章立契的女人之一。她中等身材，肩背挺直，头发分成四股在脑后盘成一个扁髻，用一根骨簪别住。她的手指关节比一般女人粗，因为十四岁起就搬斗、翻账、爬库房的架子。她穿神庙库吏的灰白色长袍，袍角永远扎在腰带里，腰带上挂着一串小木牌 —— 每一块牌子对应库房里的一间仓。她脸上很少有表情，但眼睛动得很快：谁的手往斗里多塞了一把粮，她隔十步就能看出来。她没有丈夫，也没有孩子，住库房后面的一间小屋，屋里只有一张床、一张矮桌和一摞她自己抄的旧账。',
